function run(retornoIA) {
  try {
    var obj = typeof retornoIA === "string"
      ? JSON.parse(retornoIA)
      : retornoIA;

    var resposta = obj.resposta || "";

    return String(resposta)
      .split("\\n").join("\n")
      .split("\\r").join("")
      .split("\\t").join(" ");
  } catch (e) {
    return String(retornoIA || "")
      .split("\\n").join("\n")
      .split("\\r").join("")
      .split("\\t").join(" ");
  }
}

