function run(curso) {
    var CODIGOS = ["BSI", "ENG_AUTOMACAO", "ADMINISTRACAO", "LOGISTICA", "PROCESSOS_GERENCIAIS"];

    if (curso === null || curso === undefined) {
        return "INVALIDO";
    }

    var t = String(curso).toLowerCase();

    var acentos = { "á": "a", "à": "a", "â": "a", "ã": "a", "ä": "a",
                    "é": "e", "è": "e", "ê": "e", "ë": "e",
                    "í": "i", "ì": "i", "î": "i", "ï": "i",
                    "ó": "o", "ò": "o", "ô": "o", "õ": "o", "ö": "o",
                    "ú": "u", "ù": "u", "û": "u", "ü": "u", "ç": "c" };
    t = t.replace(/[áàâãäéèêëíìîïóòôõöúùûüç]/g, function (c) { return acentos[c]; });
    t = t.replace(/[^a-z0-9]+/g, " ").replace(/^\s+|\s+$/g, "");

    var codigo = t.toUpperCase().replace(/ /g, "_");
    for (var i = 0; i < CODIGOS.length; i++) {
        if (codigo === CODIGOS[i]) {
            return CODIGOS[i];
        }
    }

    var porNumero = { "1": "BSI", "2": "ENG_AUTOMACAO", "3": "ADMINISTRACAO", "4": "LOGISTICA", "5": "PROCESSOS_GERENCIAIS" };
    if (porNumero[t]) {
        return porNumero[t];
    }

    if (/\bbsi\b|sistemas? de informa|sistemas da informa|\bsi\b/.test(t)) {
        return "BSI";
    }
    if (/engenharia|\beng\b|automa|controle/.test(t)) {
        return "ENG_AUTOMACAO";
    }
    if (/processos|gerenciais|\btpg\b/.test(t)) {
        return "PROCESSOS_GERENCIAIS";
    }
    if (/logistica|\blog\b|\btlog\b/.test(t)) {
        return "LOGISTICA";
    }
    if (/administra|\badm\b/.test(t)) {
        return "ADMINISTRACAO";
    }

    return "INVALIDO";
}

function run(ano) {
    if (ano === null || ano === undefined) {
        return "INVALIDO";
    }

    var t = String(ano).toLowerCase().replace(/^\s+|\s+$/g, "");
    var anoAtual = new Date().getFullYear();

    if (t === "todos" || /nao sou|não sou|ainda nao|ainda não|candidat|vestibular/.test(t)) {
        return "TODOS";
    }

    var m = t.match(/\b(19|20)\d{2}\b/);
    if (m) {
        var n = parseInt(m[0], 10);
        if (n > anoAtual) {
            return "INVALIDO";
        }
        if (n <= 2018) {
            return "2018";
        }
        return String(n);
    }

    var m2 = t.match(/^\d{2}$/);
    if (m2) {
        var n2 = 2000 + parseInt(t, 10);
        if (n2 > anoAtual) {
            return "INVALIDO";
        }
        return n2 <= 2018 ? "2018" : String(n2);
    }

    if (/antes/.test(t)) {
        return "2018";
    }

    return "INVALIDO";
}
